 9	/// Executes a command.
10	pub fn execute_command(
11	    mut cmd: Command,
12	    out_perm: &Mutex<()>,
13	    enable_output_buffering: bool,
14	) -> ExitCode {
15	    // Spawn the supplied command.
16	    let output = if enable_output_buffering {
17	        cmd.output()
18	    } else {
19	        // If running on only one thread, don't buffer output
20	        // Allows for viewing and interacting with intermediate command output
21	        cmd.spawn().and_then(|c| c.wait_with_output())
22	    };
23	
24	    // Then wait for the command to exit, if it was spawned.
25	    match output {
26	        Ok(output) => {
27	            // While this lock is active, this thread will be the only thread allowed
28	            // to write its outputs.
29	            let _lock = out_perm.lock().unwrap();
30	
31	            let stdout = io::stdout();
32	            let stderr = io::stderr();
33	
34	            let _ = stdout.lock().write_all(&output.stdout);
35	            let _ = stderr.lock().write_all(&output.stderr);
36	
37	            if output.status.code() == Some(0) {
38	                ExitCode::Success
39	            } else {
40	                ExitCode::GeneralError
41	            }
42	        }
43	        Err(ref why) if why.kind() == io::ErrorKind::NotFound => {
44	            print_error(format!("Command not found: {:?}", cmd));
45	            ExitCode::GeneralError
46	        }
47	        Err(why) => {
48	            print_error(format!("Problem while executing command: {}", why));
49	            ExitCode::GeneralError
50	        }
51	    }
52	}
