246	    /// Replace the path separator in the input with the custom separator string. If path_separator
247	    /// is None, simply return a borrowed Cow<OsStr> of the input. Otherwise, the input is
248	    /// interpreted as a Path and its components are iterated through and re-joined into a new
249	    /// OsString.
250	    fn replace_separator<'a>(path: &'a OsStr, path_separator: Option<&str>) -> Cow<'a, OsStr> {
251	        // fast-path - no replacement necessary
252	        if path_separator.is_none() {
253	            return Cow::Borrowed(path);
254	        }
255	
256	        let path_separator = path_separator.unwrap();
257	        let mut out = OsString::with_capacity(path.len());
258	        let mut components = Path::new(path).components().peekable();
259	
260	        while let Some(comp) = components.next() {
261	            match comp {
262	                // Absolute paths on Windows are tricky.  A Prefix component is usually a drive
263	                // letter or UNC path, and is usually followed by RootDir. There are also
264	                // "verbatim" prefixes beginning with "\\?\" that skip normalization. We choose to
265	                // ignore verbatim path prefixes here because they're very rare, might be
266	                // impossible to reach here, and there's no good way to deal with them. If users
267	                // are doing something advanced involving verbatim windows paths, they can do their
268	                // own output filtering with a tool like sed.
269	                Component::Prefix(prefix) => {
270	                    if let Prefix::UNC(server, share) = prefix.kind() {
271	                        // Prefix::UNC is a parsed version of '\\server\share'
272	                        out.push(path_separator);
273	                        out.push(path_separator);
274	                        out.push(server);
275	                        out.push(path_separator);
276	                        out.push(share);
277	                    } else {
278	                        // All other Windows prefix types are rendered as-is. This results in e.g. "C:" for
279	                        // drive letters. DeviceNS and Verbatim* prefixes won't have backslashes converted,
280	                        // but they're not returned by directories fd can search anyway so we don't worry
281	                        // about them.
282	                        out.push(comp.as_os_str());
283	                    }
284	                }
285	
286	                // Root directory is always replaced with the custom separator.
287	                Component::RootDir => out.push(path_separator),
288	
289	                // Everything else is joined normally, with a trailing separator if we're not last
290	                _ => {
291	                    out.push(comp.as_os_str());
292	                    if components.peek().is_some() {
293	                        out.push(path_separator);
294	                    }
295	                }
296	            }
297	        }
298	        Cow::Owned(out)
299	    }
300	}
